#!/usr/bin/env bash
# =============================================================================
#  CoreGSM installer  -  self-hosted game server status panel
#  Target: clean Debian 13 (trixie) / 12 (bookworm), run as root.
#
#  Interactive:      sudo bash install.sh
#  Non-interactive:  DOMAIN=gsm.example.com LE_EMAIL=me@example.com \
#                    sudo -E bash install.sh
#
#  This file is GENERATED by tools/build-installer.sh from the src/ directory.
#  Do not edit the embedded files here; edit src/ and rebuild.
# =============================================================================
set -Eeuo pipefail

# "su" without "-" keeps the caller's PATH, which lacks the sbin directories (ufw, sshd, ...)
export PATH="$PATH:/usr/local/sbin:/usr/sbin:/sbin"

APP_DIR="${APP_DIR:-/app}"
# set by tools/build-installer.sh: hash of all files embedded below (compared with version.txt in the repo)
COREGSM_BUILD="@@BUILD_ID@@"
export DEBIAN_FRONTEND=noninteractive

# ---------- colours ----------
if [ -t 1 ]; then
  RED=$'\033[1;31m'; GREEN=$'\033[1;32m'; YELLOW=$'\033[1;33m'; BLUE=$'\033[1;34m'
  MAGENTA=$'\033[1;35m'; CYAN=$'\033[1;36m'; BOLD=$'\033[1m'; DIM=$'\033[2m'; NC=$'\033[0m'
else
  RED=''; GREEN=''; YELLOW=''; BLUE=''; MAGENTA=''; CYAN=''; BOLD=''; DIM=''; NC=''
fi

LOGFILE="${COREGSM_LOG:-/var/log/coregsm-install.log}"
mkdir -p "$(dirname "$LOGFILE")" 2>/dev/null || true
IS_TTY=0; [ -t 1 ] && IS_TTY=1
# started by "coregsm update": print only the steps and their results
QUIET_OK="${COREGSM_FROM_MANAGER:-0}"
# COREGSM_VERBOSE=1: show the full output of apt/docker on the screen as well
VERBOSE="${COREGSM_VERBOSE:-0}"

# everything that is shown also goes to the log, without colour codes
logf() { printf '%s\n' "$*" | sed 's/\x1b\[[0-9;]*m//g' >> "$LOGFILE" 2>/dev/null || true; }

STEP=0
TOTAL_STEPS=11
step()  { STEP=$((STEP + 1)); echo -e "\n${BLUE}[${STEP}/${TOTAL_STEPS}]${NC} ${BOLD}$*${NC}"; logf "[${STEP}/${TOTAL_STEPS}] $*"; }
info()  { [ "$QUIET_OK" = 1 ] || echo -e "  ${CYAN}>${NC} $*"; logf "  > $*"; }
ok()    { [ "$QUIET_OK" = 1 ] || echo -e "  ${GREEN}✔${NC} $*"; logf "  ok: $*"; }
done_line() { echo -e "  ${GREEN}✔${NC} $*"; logf "  ok: $*"; }
warn()  { echo -e "  ${YELLOW}!${NC} $*"; logf "  warn: $*"; }
die()   { echo -e "\n${RED}✖ $*${NC}" >&2; logf "FATAL: $*"; exit 1; }

trap 'logf "ERROR line ${LINENO}: ${BASH_COMMAND}"; echo -e "\n${RED}✖ Установка прервана на строке ${LINENO}: ${BASH_COMMAND}${NC}\n  Подробности: ${LOGFILE}" >&2' ERR

# Runs a long command quietly: the full output goes to the log, the screen shows a spinner and one result line.
# _run "message" command...   returns the exit code of the command
_run() {
  local msg="$1"; shift
  local t0=$SECONDS rc=0 pid i=0
  local frames=(⠋ ⠙ ⠹ ⠸ ⠼ ⠴ ⠦ ⠧ ⠇ ⠏)
  printf '\n### %s: %s\n' "$msg" "$*" >> "$LOGFILE" 2>/dev/null || true
  if [ "$VERBOSE" = 1 ]; then
    echo -e "  ${CYAN}›${NC} $msg"
    set +e; "$@" 2>&1 | tee -a "$LOGFILE"; rc=${PIPESTATUS[0]}; set -e
  elif [ "$IS_TTY" = 1 ]; then
    "$@" >> "$LOGFILE" 2>&1 &
    pid=$!
    while kill -0 "$pid" 2>/dev/null; do
      printf '\r  %s%s%s %s %s%ds%s\033[K' "$CYAN" "${frames[i % 10]}" "$NC" "$msg" "$DIM" $((SECONDS - t0)) "$NC"
      i=$((i + 1)); sleep 0.12
    done
    wait "$pid" || rc=$?
    printf '\r\033[K'
  else
    echo "  … $msg"
    "$@" >> "$LOGFILE" 2>&1 || rc=$?
  fi
  if [ "$rc" -eq 0 ]; then
    done_line "$msg ${DIM}($((SECONDS - t0)) с)${NC}"
    return 0
  fi
  echo -e "  ${RED}✖${NC} $msg" >&2
  logf "  FAILED (код $rc): $msg"
  return "$rc"
}
# run: stop the installer on failure and show the tail of the log; run_soft: just report the exit code
run() {
  _run "$@" || {
    echo -e "${DIM}$(tail -n 20 "$LOGFILE" 2>/dev/null | sed 's/^/    /')${NC}" >&2
    die "Не удалось: $1. Полный журнал: $LOGFILE"
  }
}
run_soft() { _run "$@"; }

banner() {
  echo -e "${MAGENTA}"
  cat << 'ART'
   ____                 ____ ____  __  __
  / ___|___  _ __ ___  / ___/ ___||  \/  |
 | |   / _ \| '__/ _ \| |  _\___ \| |\/| |
 | |__| (_) | | |  __/| |_| |___) | |  | |
  \____\___/|_|  \___| \____|____/|_|  |_|
ART
  echo -e "${NC}${DIM}  self-hosted game server status panel + Discord cards${NC}"
}

# Read from the terminal even when the script is piped (curl ... | bash).
ask() { # ask VAR "Prompt" [default] [secret]
  local __var="$1" __prompt="$2" __def="${3:-}" __secret="${4:-}" __val=""
  if [ -n "${!__var:-}" ]; then return 0; fi
  if [ ! -r /dev/tty ]; then
    [ -n "$__def" ] && { printf -v "$__var" '%s' "$__def"; return 0; }
    die "Нет терминала для ввода. Передайте $__var через переменную окружения."
  fi
  if [ -n "$__def" ]; then __prompt="$__prompt [${__def}]"; fi
  if [ -n "$__secret" ]; then
    read -r -s -p "  ${BOLD}${__prompt}:${NC} " __val < /dev/tty; echo
  else
    read -r -p "  ${BOLD}${__prompt}:${NC} " __val < /dev/tty
  fi
  printf -v "$__var" '%s' "${__val:-$__def}"
}

gen_secret() { # gen_secret LENGTH  -> alphanumeric
  local n="$1" s=""
  while [ "${#s}" -lt "$n" ]; do
    s+="$(openssl rand -base64 48 | tr -dc 'A-Za-z0-9')"
  done
  printf '%s' "${s:0:$n}"
}

env_get() { # env_get KEY  -> value from existing .env (empty if none)
  [ -f "$APP_DIR/.env" ] || return 0
  grep -E "^$1=" "$APP_DIR/.env" | tail -n1 | cut -d= -f2- || true
}

# ---------- 1. preflight ----------
preflight() {
  step "Проверка окружения"
  [ "$(id -u)" -eq 0 ] || die "Запустите скрипт от root: sudo bash install.sh"
  [ -r /etc/os-release ] || die "Не удалось определить ОС"
  # shellcheck disable=SC1091
  . /etc/os-release
  [ "${ID:-}" = "debian" ] || warn "Скрипт рассчитан на Debian, обнаружено: ${PRETTY_NAME:-unknown}"
  case "${VERSION_ID:-}" in
    12|13) ok "ОС: ${PRETTY_NAME}" ;;
    *) warn "ОС ${PRETTY_NAME:-unknown} не проверялась (ожидается Debian 12/13). Продолжаю." ;;
  esac
  CODENAME="${VERSION_CODENAME:-bookworm}"
  case "$(uname -m)" in
    x86_64|aarch64) ok "Архитектура: $(uname -m)" ;;
    *) die "Неподдерживаемая архитектура: $(uname -m)" ;;
  esac

  local mem_mb disk_mb busy
  mem_mb="$(awk '/MemTotal/{print int($2/1024)}' /proc/meminfo)"
  [ "$mem_mb" -ge 900 ] || die "Недостаточно памяти: ${mem_mb} МБ (нужно от 1 ГБ, лучше 2 ГБ)"
  if [ "$mem_mb" -ge 1800 ]; then ok "Память: ${mem_mb} МБ"
  else warn "Памяти ${mem_mb} МБ: сборка образов может идти долго. Рекомендуется 2 ГБ"; fi
  disk_mb="$(df -Pm / | awk 'NR==2{print $4}')"
  [ "$disk_mb" -ge 4000 ] || die "Мало места на диске: свободно ${disk_mb} МБ (нужно от 4 ГБ)"
  ok "Диск: свободно ${disk_mb} МБ"
  # ports 80/443: skipped on a reinstall, where our own containers hold them
  if [ ! -f "$APP_DIR/docker-compose.yml" ]; then
    busy="$(ss -ltnH 'sport = :80 or sport = :443' 2>/dev/null | awk '{print $4}' | tr '\n' ' ' || true)"
    [ -z "$busy" ] || die "Порты 80/443 уже заняты ($busy). Остановите другой веб-сервер (nginx, apache) и запустите установку снова"
  fi
}

# ---------- 1b. proxy (optional) ----------
PROXY_MARK="# managed by CoreGSM installer"

# Accepts socks5://, socks5h://, http://, https:// (optionally with user:pass@)
valid_proxy() { [[ "$1" =~ ^(socks5h?|http|https)://([^@/[:space:]]+@)?[^@/:[:space:]]+:[0-9]{1,5}/?$ ]]; }

setup_proxy() {
  step "Прокси (необязательно)"
  : "${PROXY_URL:=$(env_get PROXY_URL)}"
  echo -e "  ${DIM}Если задан, через прокси пойдут: бот → Discord, apt, curl, загрузка образов Docker.${NC}"
  echo -e "  ${DIM}Формат: socks5://[user:pass@]host:1080  или  http://[user:pass@]host:3128${NC}"
  echo -e "  ${DIM}Опрос игровых серверов (UDP/TCP query) всегда идёт напрямую.${NC}\n"
  ask PROXY_URL "Прокси (Enter — без прокси)" "-"
  [ "$PROXY_URL" = "-" ] && PROXY_URL=""
  BUILD_PROXY=""

  if [ -z "$PROXY_URL" ]; then
    ok "Прокси не используется"
    if grep -qs "$PROXY_MARK" /etc/apt/apt.conf.d/99coregsm-proxy; then rm -f /etc/apt/apt.conf.d/99coregsm-proxy; fi
    return 0
  fi

  valid_proxy "$PROXY_URL" || die "Некорректный адрес прокси: $PROXY_URL (пример: socks5://127.0.0.1:1080)"
  # SOCKS: resolve hostnames on the proxy side (socks5h) for curl/apt
  local tool_proxy="${PROXY_URL/#socks5:/socks5h:}"
  export http_proxy="$tool_proxy" https_proxy="$tool_proxy" all_proxy="$tool_proxy"
  export HTTP_PROXY="$tool_proxy" HTTPS_PROXY="$tool_proxy" ALL_PROXY="$tool_proxy"
  export no_proxy="localhost,127.0.0.1,::1" NO_PROXY="localhost,127.0.0.1,::1"

  printf '%s\nAcquire::http::Proxy "%s";\nAcquire::https::Proxy "%s";\n' "$PROXY_MARK" "$tool_proxy" "$tool_proxy" \
    > /etc/apt/apt.conf.d/99coregsm-proxy

  if curl -fsS --max-time 15 -o /dev/null https://download.docker.com/linux/debian/gpg; then
    ok "Прокси работает"
  else
    die "Прокси недоступен или не пускает наружу: проверьте адрес, логин и пароль"
  fi

  case "$PROXY_URL" in
    http://*|https://*) BUILD_PROXY="$PROXY_URL" ;;
    *) warn "SOCKS5: npm и certbot внутри Docker не умеют SOCKS, поэтому сборка образов и продление сертификата идут напрямую." ;;
  esac
}

# The Docker daemon (image pulls) reads HTTP(S)_PROXY from a systemd drop-in; Go also accepts socks5:// there.
configure_docker_proxy() {
  local dir=/etc/systemd/system/docker.service.d
  local file=$dir/coregsm-proxy.conf tmp
  tmp="$(mktemp)"
  if [ -n "${PROXY_URL:-}" ]; then
    printf '%s\n[Service]\nEnvironment="HTTP_PROXY=%s"\nEnvironment="HTTPS_PROXY=%s"\nEnvironment="NO_PROXY=localhost,127.0.0.1,::1"\n' \
      "$PROXY_MARK" "$PROXY_URL" "$PROXY_URL" > "$tmp"
    mkdir -p "$dir"
    if ! cmp -s "$tmp" "$file"; then
      install -m 0644 "$tmp" "$file"
      systemctl daemon-reload
      systemctl restart docker
      ok "Docker настроен на работу через прокси"
    fi
  elif grep -qs "$PROXY_MARK" "$file"; then
    rm -f "$file"
    systemctl daemon-reload
    systemctl restart docker
    ok "Прокси для Docker отключён"
  fi
  rm -f "$tmp"
}

# ---------- 2. system update ----------
system_update() {
  step "Обновление системы"
  if [ "${SKIP_UPDATE:-}" = "1" ]; then
    run "Обновление списка пакетов" apt-get update -y
    ok "SKIP_UPDATE=1: полное обновление пропущено (список пакетов обновлён)"
    return 0
  fi
  run "Обновление списка пакетов" apt-get update -y
  run "Установка обновлений системы (несколько минут)" apt-get upgrade -y -o Dpkg::Options::=--force-confold -o Dpkg::Options::=--force-confdef
  ok "Система обновлена"
}

# ---------- 3. packages ----------
base_packages() {
  step "Установка curl, git, ufw и вспомогательных пакетов"
  run "Установка curl, git, ufw" apt-get install -y --no-install-recommends curl git ufw ca-certificates gnupg openssl
  ok "Базовые пакеты установлены"
}

# ---------- 4. docker ----------
install_docker() {
  step "Установка Docker Engine и Docker Compose (docker.com)"
  if command -v docker >/dev/null 2>&1 && docker compose version >/dev/null 2>&1; then
    ok "Docker уже установлен: $(docker --version)"
    configure_docker_proxy
    return 0
  fi
  install -m 0755 -d /etc/apt/keyrings
  curl -fsSL https://download.docker.com/linux/debian/gpg -o /etc/apt/keyrings/docker.asc
  chmod a+r /etc/apt/keyrings/docker.asc
  echo "deb [arch=$(dpkg --print-architecture) signed-by=/etc/apt/keyrings/docker.asc] https://download.docker.com/linux/debian ${CODENAME} stable" \
    > /etc/apt/sources.list.d/docker.list
  run "Обновление списка пакетов Docker" apt-get update -y
  run "Установка Docker Engine (1-2 минуты)" apt-get install -y docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin
  systemctl enable --now docker
  docker compose version >/dev/null 2>&1 || die "Docker Compose не установился"
  ok "Установлено: $(docker --version)"
  configure_docker_proxy
}

# ---------- 5. questions ----------
collect_input() {
  step "Настройка"
  echo -e "  ${DIM}Нужен домен с A-записью на этот сервер и e-mail для Let's Encrypt.${NC}"
  echo -e "  ${DIM}Для локальной сети достаточно IP-адреса. Токен бота и администратора вы зададите в браузере.${NC}\n"

  : "${DISCORD_TOKEN:=$(env_get DISCORD_TOKEN)}"
  : "${DOMAIN:=$(env_get DOMAIN)}"
  : "${LE_EMAIL:=$(env_get LE_EMAIL)}"

  ask DOMAIN "Домен (gsm.my-domain.com) или IP сервера для локальной сети (192.168.88.152)"
  DOMAIN="$(printf '%s' "$DOMAIN" | tr '[:upper:]' '[:lower:]')"

  if [ "${LOCAL_MODE:-}" = "1" ] || is_local_host "$DOMAIN"; then
    # Local / development: Let's Encrypt cannot issue certificates for IPs and private names.
    LOCAL_MODE=1
    [[ "$DOMAIN" =~ ^[a-z0-9]([a-z0-9.-]*[a-z0-9])?$ ]] || die "Некорректный адрес: $DOMAIN"
    LE_EMAIL=""
    ok "Локальный режим: $DOMAIN (самоподписанный сертификат, без Let's Encrypt)"
    return 0
  fi

  [[ "$DOMAIN" =~ ^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$ ]] || die "Некорректное доменное имя: $DOMAIN"

  ask LE_EMAIL "E-mail для Let's Encrypt"
  [[ "$LE_EMAIL" =~ ^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$ ]] || die "Некорректный e-mail: $LE_EMAIL"

  ok "Домен: $DOMAIN, e-mail: $LE_EMAIL"

  # DNS sanity check (warning only)
  local server_ip dns_ip
  server_ip="$(curl -4 -fsS --noproxy "*" --max-time 8 https://api.ipify.org 2>/dev/null || true)"
  dns_ip="$(getent ahostsv4 "$DOMAIN" 2>/dev/null | awk 'NR==1{print $1}' || true)"
  if [ -z "$dns_ip" ]; then
    warn "Домен $DOMAIN пока не резолвится. Выпуск сертификата, скорее всего, не удастся."
  elif [ -n "$server_ip" ] && [ "$dns_ip" != "$server_ip" ]; then
    warn "A-запись $DOMAIN указывает на $dns_ip, а IP сервера: $server_ip."
  else
    ok "DNS: $DOMAIN → ${dns_ip}"
  fi
}

# IPv4 address, "localhost", or a private suffix: Let's Encrypt is impossible for these.
is_local_host() {
  [[ "$1" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]] && return 0
  [[ "$1" =~ (^localhost$|\.(local|lan|home|internal|test|localdomain)$|\.home\.arpa$) ]] && return 0
  return 1
}

# ---------- 6. firewall ----------
setup_firewall() {
  step "Настройка файрвола UFW"
  local ssh_port
  ssh_port="$( (sshd -T 2>/dev/null | awk '/^port /{print $2; exit}') || true)"
  [ -n "$ssh_port" ] || ssh_port="$(grep -hEi '^\s*Port\s+[0-9]+' /etc/ssh/sshd_config /etc/ssh/sshd_config.d/*.conf 2>/dev/null | awk 'NR==1{print $2}' || true)"
  [ -n "$ssh_port" ] || ssh_port=22

  ufw default deny incoming >/dev/null
  ufw default allow outgoing >/dev/null
  ufw allow "${ssh_port}/tcp" comment 'SSH' >/dev/null
  ufw allow 80/tcp comment 'HTTP / ACME' >/dev/null
  ufw allow 443/tcp comment 'HTTPS' >/dev/null
  ufw --force enable >/dev/null
  ok "Открыты порты: SSH (${ssh_port}), 80, 443. Все остальные входящие закрыты."
  info "Порты backend (3000), frontend и бота наружу не публикуются: они доступны только внутри сети Docker."
}

# ---------- 7. project files ----------
@@GENERATE_FUNCTION@@

write_env() {
  step "Генерация секретов и .env"
  local jwt internal
  SETUP_TOKEN="$(env_get SETUP_TOKEN)"; [ -n "$SETUP_TOKEN" ] || SETUP_TOKEN="$(gen_secret 16)"
  jwt="$(env_get JWT_SECRET)";          [ -n "$jwt" ]      || jwt="$(gen_secret 64)"
  internal="$(env_get INTERNAL_TOKEN)"; [ -n "$internal" ] || internal="$(gen_secret 48)"
  umask 077
  cat > "$APP_DIR/.env" << ENVFILE
# Generated by CoreGSM installer. Keep this file private (chmod 600).
DOMAIN=${DOMAIN}
LE_EMAIL=${LE_EMAIL}
# optional first-start defaults; afterwards the token and proxy are managed in the web panel (Settings)
DISCORD_TOKEN=${DISCORD_TOKEN:-}
# socks5://[user:pass@]host:port or http://[user:pass@]host:port; empty = no proxy
PROXY_URL=${PROXY_URL:-}
# http(s) proxy for Docker image builds and certbot renewal (SOCKS is not supported there)
BUILD_PROXY=${BUILD_PROXY:-}
# installed build, compared with version.txt in the repository
APP_VERSION=${COREGSM_BUILD}
# one-time code for the first-run setup wizard in the browser
SETUP_TOKEN=${SETUP_TOKEN}
JWT_SECRET=${jwt}
INTERNAL_TOKEN=${internal}
POLL_INTERVAL_SEC=30
ENVFILE
  chmod 600 "$APP_DIR/.env"
  umask 022
  ok "Секреты записаны в $APP_DIR/.env (права 600)"
}

# ---------- 8. TLS ----------
issue_certificate() {
  local conf="$APP_DIR/certbot/conf" live="$APP_DIR/certbot/conf/live/$DOMAIN"
  mkdir -p "$conf" "$APP_DIR/certbot/www"

  if [ "${LOCAL_MODE:-}" = "1" ]; then
    step "SSL-сертификат для локального режима (самоподписанный)"
    if [ -f "$APP_DIR/docker-compose.yml" ]; then
      (cd "$APP_DIR" && docker compose down >/dev/null 2>&1) || true
    fi
    rm -rf "$live"
    mkdir -p "$live"
    local san="DNS:${DOMAIN}"
    [[ "$DOMAIN" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]] && san="IP:${DOMAIN}"
    openssl req -x509 -nodes -newkey rsa:2048 -days 825 -subj "/CN=${DOMAIN}" -addext "subjectAltName=${san}" \
      -keyout "$live/privkey.pem" -out "$live/fullchain.pem" >/dev/null 2>&1
    touch "$live/.selfsigned"
    CERT_MODE="local"
    ok "Сертификат создан (825 дней). Браузер покажет предупреждение: это ожидаемо."
    return 0
  fi

  step "Выпуск SSL-сертификата Let's Encrypt (Certbot в Docker)"

  # Stop a previous stack so port 80 is free for the standalone challenge.
  if [ -f "$APP_DIR/docker-compose.yml" ]; then
    (cd "$APP_DIR" && docker compose down >/dev/null 2>&1) || true
  fi

  if [ -f "$live/.selfsigned" ]; then rm -rf "$live" "$conf/archive/$DOMAIN" "$conf/renewal/$DOMAIN.conf"; fi

  if [ -f "$live/fullchain.pem" ]; then
    ok "Действующий сертификат для $DOMAIN уже есть, выпуск пропущен"
    CERT_MODE="letsencrypt"
    return 0
  fi

  if run_soft "Выпуск сертификата Let's Encrypt" docker run --rm -p 80:80 ${BUILD_PROXY:+-e HTTPS_PROXY=$BUILD_PROXY} \
      -v "$conf:/etc/letsencrypt" -v "$APP_DIR/certbot/www:/var/www/certbot" \
      certbot/certbot certonly --standalone --non-interactive --agree-tos --no-eff-email \
      -m "$LE_EMAIL" -d "$DOMAIN"; then
    CERT_MODE="letsencrypt"
    ok "Сертификат Let's Encrypt выпущен. Автопродление: контейнер certbot."
  else
    warn "Не удалось получить сертификат (проверьте A-запись домена и доступность порта 80)."
    warn "Создаю временный самоподписанный сертификат, чтобы панель всё равно запустилась."
    mkdir -p "$live"
    openssl req -x509 -nodes -newkey rsa:2048 -days 30 -subj "/CN=${DOMAIN}" \
      -keyout "$live/privkey.pem" -out "$live/fullchain.pem" >/dev/null 2>&1
    touch "$live/.selfsigned"
    CERT_MODE="selfsigned"
  fi
}

# ---------- 9. launch ----------
launch() {
  step "Сборка и запуск контейнеров"
  cd "$APP_DIR"
  run "Сборка образов и запуск контейнеров (3-8 минут)" docker compose up --build -d
  info "Жду готовности панели…"
  local i
  for i in $(seq 1 60); do
    if curl -fsk --noproxy "*" --max-time 3 --resolve "${DOMAIN}:443:127.0.0.1" "https://${DOMAIN}/api/health" >/dev/null 2>&1; then
      ok "Панель отвечает"
      return 0
    fi
    sleep 3
  done
  warn "Панель не ответила за 3 минуты. Логи: cd $APP_DIR && docker compose logs --tail=100"
}

report() {
  local line="════════════════════════════════════════════════════════════"
  echo -e "\n${GREEN}${line}${NC}"
  echo -e "${GREEN}  ✔  CoreGSM установлен${NC}"
  echo -e "${GREEN}${line}${NC}"
  echo -e "  ${BOLD}Панель:${NC}   ${CYAN}https://${DOMAIN}${NC}"
  if curl -fsk --noproxy "*" --max-time 5 --resolve "${DOMAIN}:443:127.0.0.1" "https://${DOMAIN}/api/setup/status" 2>/dev/null | grep -q '"needed":true'; then
    echo -e "  ${BOLD}Код установки:${NC} ${YELLOW}${SETUP_TOKEN}${NC}"
    echo -e "${GREEN}${line}${NC}"
    echo -e "  Откройте панель в браузере и пройдите первичную настройку:"
    echo -e "  введите код установки, придумайте логин и пароль администратора."
  else
    echo -e "${GREEN}${line}${NC}"
    echo -e "  Панель уже настроена: войдите под своим логином и паролем."
  fi
  echo -e "${GREEN}${line}${NC}"
  if [ "${CERT_MODE:-}" = "local" ]; then
    echo -e "  ${YELLOW}Локальный режим:${NC} сертификат самоподписанный, браузер покажет предупреждение."
    echo -e "  Нажмите «Дополнительно» → «Перейти на ${DOMAIN}»."
  fi
  if [ "${CERT_MODE:-}" = "selfsigned" ]; then
    echo -e "  ${RED}Сертификат самоподписанный${NC}: браузер покажет предупреждение."
    echo -e "  Настройте A-запись ${DOMAIN} на этот сервер и повторите: ${BOLD}sudo bash install.sh${NC}"
  fi
  echo -e "  ${DIM}Секреты:  ${APP_DIR}/.env      Логи:  cd ${APP_DIR} && docker compose logs -f${NC}"
  echo -e "  ${DIM}Управление, обновление, копии, удаление:  sudo coregsm${NC}"
  echo -e "  ${DIM}Токен Discord-бота, прокси и пароль: в панели, раздел «Настройки».${NC}\n"
}

# /usr/local/bin/coregsm (the manager, see tools/coregsm.sh), the old coregsm-update name as an alias,
# bash completion and the systemd path unit behind the panel's "Update" button.
install_manager() {
  cat > /usr/local/bin/.coregsm.new << 'MANAGER'
@@MANAGER_SCRIPT@@
MANAGER
  chmod +x /usr/local/bin/.coregsm.new
  # atomic replace: a manager that is running right now keeps reading its old file safely
  mv -f /usr/local/bin/.coregsm.new /usr/local/bin/coregsm

  printf '#!/bin/sh\nexec /usr/local/bin/coregsm update "$@"\n' > /usr/local/bin/.coregsm-update.new
  chmod +x /usr/local/bin/.coregsm-update.new
  mv -f /usr/local/bin/.coregsm-update.new /usr/local/bin/coregsm-update

  mkdir -p /etc/bash_completion.d
  cat > /etc/bash_completion.d/coregsm << 'COMP'
_coregsm() {
  local cur="${COMP_WORDS[COMP_CWORD]}"
  if [ "$COMP_CWORD" -eq 1 ]; then
    COMPREPLY=($(compgen -W "update status doctor logs start stop restart backup restore domain reset-password uninstall help" -- "$cur"))
  fi
}
complete -F _coregsm coregsm
COMP

  # the panel (container user "node", uid 1000) may only drop a request file here; root does the work
  mkdir -p "$APP_DIR/update"
  chown 1000:1000 "$APP_DIR/update"
  chmod 755 "$APP_DIR/update"

  if [ -d /run/systemd/system ]; then
    cat > /etc/systemd/system/coregsm-update.service << UNIT
[Unit]
Description=CoreGSM update (started from the web panel)

[Service]
Type=oneshot
Environment=APP_DIR=${APP_DIR}
ExecStart=/usr/local/bin/coregsm update --from-panel
TimeoutStartSec=1800
UNIT
    cat > /etc/systemd/system/coregsm-update.path << UNIT
[Unit]
Description=Watch for update requests from the CoreGSM web panel

[Path]
PathExists=${APP_DIR}/update/request
Unit=coregsm-update.service

[Install]
WantedBy=multi-user.target
UNIT
    systemctl daemon-reload
    systemctl enable --now coregsm-update.path >/dev/null 2>&1 \
      && ok "Команда coregsm и кнопка «Обновить» в панели включены" \
      || warn "Не удалось включить systemd-юнит coregsm-update.path: кнопка в панели работать не будет, обновляйте командой sudo coregsm update"
  else
    ok "Команда coregsm установлена"
    warn "systemd не найден: кнопка «Обновить» в панели недоступна, используйте sudo coregsm update"
  fi
}

installed_already() { [ -f "$APP_DIR/.env" ] && [ -f "$APP_DIR/docker-compose.yml" ] && [ -x /usr/local/bin/coregsm ]; }

main() {
  local do_install=0 arg
  for arg in "$@"; do
    case "$arg" in
      --install) do_install=1 ;;
      -h|--help)
        cat << 'HELP'
CoreGSM: установка и управление.

  bash install.sh             установить; если CoreGSM уже стоит, откроет меню управления
  bash install.sh --install   выполнить установку или переустановку без меню
  coregsm                     меню управления (после установки доступно из любой папки)

Переменные окружения: DOMAIN, LE_EMAIL, PROXY_URL, SKIP_UPDATE=1, LOCAL_MODE=1
HELP
        exit 0 ;;
      *) die "Неизвестный параметр: $arg (см. bash install.sh --help)" ;;
    esac
  done

  # On a machine that already runs CoreGSM a plain "bash install.sh" opens the management menu.
  # --install, SKIP_UPDATE=1 (older updaters, dev flows) or a non-interactive shell run the installer.
  if [ "$do_install" = 0 ] && [ -z "${SKIP_UPDATE:-}" ] && [ -t 0 ] && [ -t 1 ] && installed_already; then
    exec /usr/local/bin/coregsm
  fi

  logf "=== CoreGSM install $(date -u '+%F %T') UTC, build $COREGSM_BUILD ==="

  banner
  preflight
  setup_proxy
  system_update
  base_packages
  install_docker
  collect_input
  setup_firewall
  step "Создание файлов проекта в $APP_DIR"
  generate_project
  ok "Файлы проекта созданы"
  write_env
  install_manager
  issue_certificate
  launch
  report
}

main "$@"
